// ─── Списки устройств для выбора в настройках ───────────────────────────────
var occList    = getServiceList([HS.OccupancySensor], HC.OccupancyDetected);
var geoList    = getServiceList([HS.C_Massage, HS.Switch], HC.On);
var switchList = getServiceList([HS.Switch], HC.On);

info = {
  name: "🏠 Присутствие жильца — слияние источников",
  description: "Итоговый датчик присутствия одного жильца по геозоне, Homebridge, плагину роутера, входной двери и активному ping телефона по IP. Приход — сразу по любому сильному признаку, уход — по совокупности признаков. Источники отслеживаются по событиям. Привязывается к «Обнаружено присутствие» ИТОГОВОГО датчика жильца, один экземпляр на человека.",
  version: "1.8",
  author: "Andrey",
  onStart: true,

  sourceServices: [HS.OccupancySensor],
  sourceCharacteristics: [HC.OccupancyDetected],

  options: {
    // ── Источники ──────────────────────────────────────────────────────────
    geoService: {
      name: { ru: "1. Геозона iPhone (выключатель)", en: "Geofence switch" },
      desc: { ru: "ВКЛ — в геозоне, ВЫКЛ — вне. Может врать при глушилках и залипать во ВКЛ без интернета.", en: "ON = inside geofence" },
      type: "String", value: "", formType: "list", values: geoList
    },
    hbService: {
      name: { ru: "2. Датчик Homebridge", en: "Homebridge occupancy sensor" },
      type: "String", value: "", formType: "list", values: occList
    },
    routerService: {
      name: { ru: "3. Датчик плагина роутера", en: "Router plugin occupancy sensor" },
      desc: { ru: "Приход — быстро, уход — с запаздыванием до ~10 мин.", en: "Fast on arrival, lags on leave" },
      type: "String", value: "", formType: "list", values: occList
    },
    routerOfflineIsAway: {
      name: { ru: "Роутер: «не в сети» (offline) = нет", en: "Router offline = not present" },
      desc: { ru: "Плагин роутера делает устройство недоступным, когда телефона нет в сети. ВКЛ — считать это отсутствием, а не «нет данных».", en: "" },
      type: "Boolean", value: true
    },
    routerHealthService: {
      name: { ru: "Контроль плагина роутера (сам роутер)", en: "Router plugin health device" },
      desc: { ru: "Датчик самого роутера из того же плагина. Если он не «в сети» — плагин не работает, данные роутера по телефону не учитываются.", en: "" },
      type: "String", value: "", formType: "list", values: occList
    },
    doorInService: {
      name: { ru: "4. Дверь: открытие ИЗНУТРИ (выход)", en: "Door opened from inside" },
      type: "String", value: "", formType: "list", values: switchList
    },
    doorOutService: {
      name: { ru: "5. Дверь: открытие СНАРУЖИ (вход)", en: "Door opened from outside" },
      desc: { ru: "Подсказка: после входа сценарий сразу пингует телефон.", en: "Triggers an immediate ping" },
      type: "String", value: "", formType: "list", values: switchList
    },
    ipAddress: {
      name: { ru: "IP телефона для активного ping", en: "Phone IP for active ping" },
      desc: { ru: "Пусто — сценарий сам не пингует и не требует провала ping для ухода.", en: "Empty = no active ping" },
      type: "String", value: ""
    },

    // ── Уход: быстрый путь (телефон пропал вместе с выходом) ────────────────
    leaveFastMin: {
      name: { ru: "Быстрый уход: сеть молчит при геозоне ВЫКЛ (мин)", en: "Fast leave, geofence OFF (min)" },
      desc: { ru: "Выход в дверь и телефон пропал из сети рядом с ним, либо после двери сработал выход из геозоны.", en: "" },
      type: "Integer", value: 3
    },
    leaveDoorMin: {
      name: { ru: "Уход по двери при геозоне ВКЛ (мин)", en: "Door leave, geofence ON (min)" },
      desc: { ru: "Телефон был в сети перед выходом и пропал после него, а геозона не выключилась (залипла).", en: "" },
      type: "Integer", value: 10
    },
    doorCorrMin: {
      name: { ru: "Телефон в сети до выхода, не позже (мин)", en: "Seen before exit within (min)" },
      desc: { ru: "Если телефон был в сети не раньше чем за N мин до открытия двери — выход считается его.", en: "" },
      type: "Integer", value: 5
    },
    doorSlackMin: {
      name: { ru: "Телефон в сети после выхода, допуск (мин)", en: "Seen after exit slack (min)" },
      desc: { ru: "Сколько телефон может ещё «светиться» в Wi-Fi после выхода (лифт, подъезд).", en: "" },
      type: "Integer", value: 5
    },

    // ── Уход: медленный путь (телефон давно спит) ──────────────────────────
    leaveSlowMin: {
      name: { ru: "Медленный уход: сеть молчит днём (мин)", en: "Slow leave, day (min)" },
      desc: { ru: "Когда выход в дверь не связан с пропаданием телефона (давно спал). 0 — никогда.", en: "0 = never" },
      type: "Integer", value: 90
    },
    nightSlowMin: {
      name: { ru: "Медленный уход: сеть молчит ночью (мин)", en: "Slow leave, night (min)" },
      desc: { ru: "0 — ночью по медленному пути не уходить никогда.", en: "0 = never" },
      type: "Integer", value: 0
    },
    nightStart: { name: { ru: "Начало ночи (ЧЧ:ММ)", en: "Night start" }, type: "String", value: "23:00" },
    nightEnd:   { name: { ru: "Конец ночи (ЧЧ:ММ)",  en: "Night end"   }, type: "String", value: "08:00" },
    requireDoor: {
      name: { ru: "Уход только после открытия двери изнутри", en: "Leave requires door exit" },
      desc: { ru: "Работает, если выбран датчик 4.", en: "Needs sensor 4" },
      type: "Boolean", value: true
    },
    routerLagMin: {
      name: { ru: "Запаздывание роутера при уходе (мин)", en: "Router leave lag (min)" },
      desc: { ru: "При геозоне ВЫКЛ после выхода «в сети» от роутера столько минут не учитывается. Ставьте чуть больше реального лага.", en: "" },
      type: "Integer", value: 12
    },
    resetGeoOnAway: {
      name: { ru: "Выключать геозону при уходе", en: "Reset geofence on leave" },
      desc: { ru: "Снимает залипшее ВКЛ, чтобы следующий вход в геозону всегда давал событие. Не срабатывает, если уход решён по самой геозоне.", en: "" },
      type: "Boolean", value: true
    },
    syncGeoOnLan: {
      name: { ru: "Включать геозону при приходе по сети", en: "Set geofence ON on LAN arrival" },
      desc: { ru: "Если геозона не сработала, а телефон появился в сети — включить её. Минус: iPhone не видел входа и может не прислать выход, тогда уход будет по двери и таймауту (медленнее). Включайте, только если геозона нужна другим автоматизациям.", en: "" },
      type: "Boolean", value: false
    },

    // ── Приход ─────────────────────────────────────────────────────────────
    geoArrive: {
      name: { ru: "Приход по геозоне сразу", en: "Arrive on geofence" },
      type: "Boolean", value: true
    },
    geoConfirmMin: {
      name: { ru: "Подтверждение прихода по геозоне (мин)", en: "Geofence arrival confirm (min)" },
      desc: { ru: "Если за это время нет ни сети, ни входа в дверь — приход отменяется. 0 — не проверять.", en: "0 = no check" },
      type: "Integer", value: 30
    },
    geoWaitMin: {
      name: { ru: "Ожидание входа после неподтверждённой геозоны (мин)", en: "Wait for door after unconfirmed geofence (min)" },
      desc: { ru: "Приход по геозоне отменён (например, зашёл в магазин). Пока геозона ВКЛ и не прошло N мин, вход в дверь снаружи засчитывает приход даже без сети. 0 — выкл.", en: "0 = off" },
      type: "Integer", value: 180
    },
    geoEntryWindowMin: {
      name: { ru: "Вход в дверь рядом с геозоной, ± (мин)", en: "Door entry window around geofence (min)" },
      desc: { ru: "Открытие двери снаружи в пределах ±N мин от срабатывания геозоны подтверждает приход (геозона часто опаздывает).", en: "" },
      type: "Integer", value: 10
    },

    startVerifyMin: {
      name: { ru: "Проверка после перезапуска (мин)", en: "Post-restart check (min)" },
      desc: { ru: "После старта в состоянии «дома»: если телефон так и не появился в сети, геозона ВЫКЛ и ping не отвечает — через N мин считать, что человека нет.", en: "" },
      type: "Integer", value: 5
    },

    // ── Активный ping ──────────────────────────────────────────────────────
    pingIntervalSec: {
      name: { ru: "Интервал активного ping (сек)", en: "Active ping interval (s)" },
      desc: { ru: "Пингуем только когда сеть молчит и человек числится дома.", en: "" },
      type: "Integer", value: 60
    },
    pingTries: {
      name: { ru: "Попыток ping в серии", en: "Ping tries per burst" },
      type: "Integer", value: 2
    },
    pingFailBursts: {
      name: { ru: "Проваленных серий подряд для ухода", en: "Failed bursts to leave" },
      type: "Integer", value: 2
    },

    // ── Служебное ──────────────────────────────────────────────────────────
    tickSec: {
      name: { ru: "Пересчёт таймаутов (сек, 10–60)", en: "Timeout check period (s)" },
      desc: { ru: "Источники отслеживаются по событиям мгновенно. Этот период нужен только для проверки истёкших таймаутов и активного ping.", en: "" },
      type: "Integer", value: 30
    },
    // ── Telegram: критические ошибки ─────────────────────────────────────
    tgEnabled: {
      name: { ru: "Telegram: отправлять критические ошибки", en: "Telegram alerts" },
      desc: { ru: "Недоступность источников и переход на запасную логику, а также восстановление. Приход/уход не отправляются.", en: "" },
      type: "Boolean", value: false
    },
    tgChannel: {
      name: { ru: "Telegram: канал уведомлений (запасной)", en: "Notify channel (fallback)" },
      desc: { ru: "Основной путь — глобальная функция sendTG. Если её нет, отправка через Notify в этот канал.", en: "" },
      type: "String", value: "telegram_1"
    },
    tgShared: {
      name: { ru: "Telegram: сообщать об общих устройствах", en: "Report shared devices" },
      desc: { ru: "Дверь и плагин роутера общие для всех жильцов. Включите только в ОДНОМ экземпляре сценария, иначе сообщения будут дублироваться.", en: "" },
      type: "Boolean", value: true
    },
    homeUnconfirmedHours: {
      name: { ru: "Сообщать: «дома» без подтверждения (ч)", en: "Alert: home unconfirmed (h)" },
      desc: { ru: "Человек числится дома N часов, но телефона нет в сети и геозона не ВКЛ. Из-за этого может не включиться режим «не дома» и камеры. Только сообщение, состояние не меняется. 0 — выкл.", en: "0 = off" },
      type: "Integer", value: 6
    },
    alertDelayMin: {
      name: { ru: "Сообщать, если проблема держится (мин)", en: "Alert after (min)" },
      desc: { ru: "Защита от кратковременных пропаданий: сообщение уходит, только если состояние держится N мин.", en: "" },
      type: "Integer", value: 5
    },
    tgTest: {
      name: { ru: "Telegram: тест при сохранении", en: "Telegram test on save" },
      desc: { ru: "Отправить тестовое сообщение при старте сценария. Выключите после проверки.", en: "" },
      type: "Boolean", value: false
    },
    pingLogVerbose: {
      name: { ru: "Подробный лог ping", en: "Verbose ping log" },
      desc: { ru: "Писать каждую серию активного ping: зачем пинговали, ответил или нет, сколько заняло. Для отладки.", en: "" },
      type: "Boolean", value: false
    },
    logEnabled: {
      name: { ru: "Логирование событий", en: "Event logging" },
      desc: { ru: "Приход/уход с причиной, подписка, активный ping. Ошибки пишутся всегда.", en: "" },
      type: "Boolean", value: false
    }
  },

  variables: {
    opts: undefined, cron: undefined, cronSig: undefined, sub: undefined, subLogged: undefined,
    busy: undefined, outSvc: undefined, label: undefined,
    state: undefined, arrivedAt: undefined, awayAt: undefined,
    lastSeenLAN: undefined, lastSeenStrong: undefined, lastSeenReal: undefined,
    geoOffAt: undefined, geoOnAt: undefined, geoArrivedAt: undefined,
    lastExitAt: undefined, lastEntryAt: undefined,
    lastPingAt: undefined, failedBursts: undefined,
    armed: undefined, prev: undefined, startCheck: undefined, geoWaitUntil: undefined, health: undefined, unconfAlerted: undefined
  }
};

var TAG = "[Присутствие] ";

// ═══════════════════════════════════════════════════════════════════════════
// ТОЧКА ВХОДА — изменение итогового датчика и старт
// ═══════════════════════════════════════════════════════════════════════════
function trigger(source, value, variables, options, context) {
  try {
    variables.opts = options;                    // актуальные настройки для подписки и cron
    var svc = source.getService();
    variables.outSvc = svc;
    if (!variables.label) variables.label = makeLabel(svc);

    var v = (typeof value === "object" && value !== null) ? value.value : value;
    var cur = (v === 1 || v === true || v === "1") ? 1 : 0;

    if (variables.state !== 0 && variables.state !== 1) {
      initState(cur, variables, options);
    } else if (cur !== variables.state && !variables.busy) {
      // Итоговый датчик изменили вручную — принимаем как новое состояние
      if (cur === 1) markHome(variables, Date.now(), true);
      else markAway(variables, Date.now());
      log(options, variables, "ручное изменение → " + (cur ? "ДОМА" : "НЕТ ДОМА"));
    }

    setupSubscription(variables);
    setupCron(variables);
    tick(variables);
  } catch (e) {
    console.error(TAG + "trigger: " + e.message);
  }
}

function initState(cur, variables, options) {
  var now = Date.now();
  variables.prev = {};
  variables.failedBursts = 0;
  variables.lastPingAt = 0;
  readInputs(options, variables, now);          // запомнить текущие значения без фронтов
  if (cur === 1) {
    markHome(variables, now, false);            // после рестарта: пока телефон не появится в сети,
    variables.lastSeenReal = undefined;         // уход — только по геозоне или стартовой проверке
    variables.startCheck = true;
  } else {
    markAway(variables, now);
    variables.armed = { hb: true, router: true };
  }
  log(options, variables, "старт, состояние " + (cur ? "ДОМА" : "НЕТ ДОМА"));
  if (options.logEnabled) {
    logSources(options, variables);
    var ip = trimStr(options.ipAddress);
    if (ip) {
      var t0 = Date.now();
      var ok = pingBurst(ip, options);
      log(options, variables, "тест ping " + ip + ": " + (ok ? "ОТВЕТИЛ" : "нет ответа") + " за " + (Date.now() - t0) + " мс");
    } else {
      log(options, variables, "IP для активного ping не задан — ping не используется");
    }
  }
  if (options.tgEnabled && options.tgTest) {
    sendTg(options, variables, "🔔 тестовое сообщение, сценарий запущен (состояние: " + (cur ? "дома" : "нет дома") + ")");
  }
}

// Какие устройства реально найдены по выбранным UUID и что они показывают
function logSources(options, variables) {
  var list = [
    ["геозона",       options.geoService,     HC.On],
    ["HB",            options.hbService,      HC.OccupancyDetected],
    ["роутер",        options.routerService,  HC.OccupancyDetected, options.routerOfflineIsAway],
    ["дверь изнутри", options.doorInService,  HC.On],
    ["дверь снаружи", options.doorOutService, HC.On]
  ];
  for (var i = 0; i < list.length; i++) {
    var uuid = trimStr(list[i][1]), txt;
    if (!uuid) {
      txt = "не выбран";
    } else {
      var svc = getService(uuid);
      if (!svc) {
        txt = "НЕ НАЙДЕН (" + uuid + ")";
      } else {
        var v = readChar(uuid, list[i][2], list[i][3]);
        var shown = (v === 0 && list[i][3] && readChar(uuid, list[i][2]) === null) ? "offline = НЕТ"
                  : (v === null) ? "нет данных/offline"
                  : (v === true || v === 1 || v === "1" || v === "true") ? (list[i][2] === HC.On ? "ВКЛ" : "ДА") : (list[i][2] === HC.On ? "ВЫКЛ" : "НЕТ");
        txt = makeLabel(svc) + " (" + uuid + "): " + shown;
      }
    }
    log(options, variables, "источник " + list[i][0] + " = " + txt);
  }
}

// ═══════════════════════════════════════════════════════════════════════════
// ПОДПИСКА НА ИЗМЕНЕНИЯ ИСТОЧНИКОВ
// ═══════════════════════════════════════════════════════════════════════════
function setupSubscription(variables) {
  if (variables.sub) return;
  try {
    variables.sub = Hub.subscribeWithCondition("", "",
      [HS.OccupancySensor, HS.Switch, HS.C_Massage],
      [HC.OccupancyDetected, HC.On],
      function () {
        try { onSourceEvent(arguments, variables); }
        catch (e) { console.error(TAG + "событие: " + e.message); }
      });
    log(variables.opts, variables, "подписка на источники активна");
  } catch (e) {
    variables.sub = undefined;
    console.warn(TAG + "подписка не создана (" + e.message + "), работаю только по таймеру — короткое открытие двери может быть пропущено");
    sendTg(variables.opts, variables, "⚠️ подписка на события не создана (" + e.message + "). Работаю по таймеру, короткое открытие двери может быть пропущено.");
  }
}

function onSourceEvent(args, variables) {
  var options = variables.opts;
  if (!options) return;
  var uuid = eventServiceUuid(args);

  if (!variables.subLogged) {
    variables.subLogged = true;
    log(options, variables, "первое событие подписки: аргументов " + args.length + ", сервис " + (uuid || "не определён"));
  }

  // Сервис определить не удалось — пересчитываем на всякий случай (дёшево)
  if (uuid && !isOurSource(uuid, options)) return;
  tick(variables);
}

// Ищет среди аргументов обработчика сервис (или характеристику) и возвращает UUID сервиса
function eventServiceUuid(args) {
  for (var i = 0; i < args.length; i++) {
    var a = args[i];
    if (a === null || a === undefined || typeof a !== "object") continue;
    try {
      if (typeof a.getCharacteristic === "function" && typeof a.getUUID === "function") return String(a.getUUID());
      if (typeof a.getService === "function") {
        var s = a.getService();
        if (s && typeof s.getUUID === "function") return String(s.getUUID());
      }
    } catch (e) {}
  }
  return null;
}

function isOurSource(uuid, options) {
  var list = [options.geoService, options.hbService,
              options.routerService, options.doorInService, options.doorOutService];
  for (var i = 0; i < list.length; i++) if (list[i] && list[i] === uuid) return true;
  return false;
}

// ═══════════════════════════════════════════════════════════════════════════
// ТАЙМЕР — только истёкшие таймауты и активный ping
// ═══════════════════════════════════════════════════════════════════════════
function setupCron(variables) {
  var sec = clampInt(variables.opts.tickSec, 10, 60, 30);
  var sig = "t" + sec;
  if (variables.cron && variables.cronSig === sig) return;
  if (variables.cron) { variables.cron.clear(); variables.cron = undefined; }
  variables.cronSig = sig;
  var expr = (sec === 60) ? "0 * * * * *" : "*/" + sec + " * * * * *";
  variables.cron = Cron.schedule(expr, function () {
    try { tick(variables); }
    catch (e) { console.error(TAG + "cron: " + e.message); }
  });
}

function tick(variables) {
  var options = variables.opts;
  if (!options || variables.busy) return;
  if (variables.state !== 0 && variables.state !== 1) return;
  variables.busy = true;
  try {
    var now = Date.now();
    var inp = readInputs(options, variables, now);
    checkHealth(inp, now, variables, options);
    if (variables.state === 1) evalHome(inp, now, variables, options);
    else evalAway(inp, now, variables, options);
  } finally {
    variables.busy = false;
  }
}

// Читает источники, ловит фронты геозоны и двери, «взводит» LAN-источники
function readInputs(options, variables, now) {
  var p = variables.prev || {};
  var inp = {
    geo:     readBool(options.geoService, HC.On),
    hb:      readOcc(options.hbService),
    router:  readOcc(options.routerService, options.routerOfflineIsAway),
    routerPlugin: trimStr(options.routerHealthService) ? (readOcc(options.routerHealthService) === true) : null,
    doorIn:  readBool(options.doorInService, HC.On),
    doorOut: readBool(options.doorOutService, HC.On)
  };

  // Плагин роутера не работает — данные роутера по телефону «нет данных»
  if (inp.routerPlugin === false) inp.router = null;

  if (p.init) {
    if (p.geo === true  && inp.geo === false) variables.geoOffAt = now;
    if (p.geo === false && inp.geo === true)  variables.geoOnAt  = now;
    if (inp.doorIn  === true && p.doorIn  !== true) variables.lastExitAt  = now;
    if (inp.doorOut === true && p.doorOut !== true) variables.lastEntryAt = now;
  }
  if (inp.geo !== null)     p.geo = inp.geo;
  if (inp.doorIn !== null)  p.doorIn = inp.doorIn;
  if (inp.doorOut !== null) p.doorOut = inp.doorOut;
  p.init = true;
  variables.prev = p;

  // Источник «взводится», когда после ухода хоть раз показал «нет в сети».
  // Так запаздывающее «в сети» сразу после ухода не вернёт человека домой.
  var a = variables.armed || { hb: true, router: true };
  if (inp.hb === false)     a.hb = true;
  if (inp.router === false) a.router = true;
  variables.armed = a;
  return inp;
}

// ═══════════════════════════════════════════════════════════════════════════
// ЧЕЛОВЕК ДОМА — ищем основания для ухода
// ═══════════════════════════════════════════════════════════════════════════
function evalHome(inp, now, variables, options) {
  var slack  = minToMs(options.doorSlackMin, 5);
  var corr   = minToMs(options.doorCorrMin, 5);
  var lagMs  = minToMs(options.routerLagMin, 12);
  var arr    = variables.arrivedAt || 0;

  // Геозона: ВЫКЛ считается «вне зоны», только если выключилась ПОСЛЕ прихода.
  // Устаревшее ВЫКЛ (пропущенный вход, сброс) — «нет данных».
  var gOffFresh = (variables.geoOffAt || 0) > arr ? variables.geoOffAt : 0;
  var geo = inp.geo;
  if (geo === false && !gOffFresh) geo = null;

  // 1. Сильный LAN-признак: HB
  if (inp.hb === true) {
    seenLAN(variables, now, true);
    return;
  }

  // 2. Роутер. Игнорируем только при свежем выходе из геозоны и недавнем признаке ухода:
  //    тогда его «в сети» может быть просто запаздыванием.
  if (inp.router === true) {
    var hint = leaveHintAt(variables, slack);
    var inLag = geo === false && hint && (now - hint) < lagMs;
    if (!inLag) { seenLAN(variables, now, false); return; }
  }

  // 3. Приход только по геозоне — ждём подтверждения сетью или входом в дверь (±окно)
  var confirmMs = minToMs(options.geoConfirmMin, 30);
  if (variables.geoArrivedAt) {
    var win = minToMs(options.geoEntryWindowMin, 10);
    if (variables.lastEntryAt && variables.lastEntryAt >= variables.geoArrivedAt - win) {
      variables.geoArrivedAt = undefined;
      log(options, variables, "приход по геозоне подтверждён входом в дверь");
    } else if (confirmMs > 0 && now - variables.geoArrivedAt >= confirmMs) {
      setAway(variables, options, now, "приход по геозоне не подтвердился за " + options.geoConfirmMin + " мин", false);
      var waitMs = minToMs(options.geoWaitMin, 180);
      if (waitMs > 0) {
        variables.geoWaitUntil = now + waitMs;
        log(options, variables, "жду входа в дверь, пока геозона ВКЛ (до " + options.geoWaitMin + " мин)");
      }
      return;
    }
  }

  // 4. Сеть молчит — активный ping (заодно пытается разбудить телефон)
  var ip = trimStr(options.ipAddress);
  if (ip && now - (variables.lastPingAt || 0) >= clampInt(options.pingIntervalSec, 10, 3600, 60) * 1000) {
    variables.lastPingAt = now;
    if (doPing(ip, options, variables, "дома, сеть молчит")) {
      if ((variables.failedBursts || 0) > 0) log(options, variables, "активный ping снова отвечает");
      seenLAN(variables, now, true);
      return;
    }
    variables.failedBursts = (variables.failedBursts || 0) + 1;
    if (variables.failedBursts === 1 || variables.failedBursts === clampInt(options.pingFailBursts, 1, 20, 2)) {
      log(options, variables, "активный ping без ответа, серий подряд: " + variables.failedBursts);
    }
  }
  var pingOk = !ip || (variables.failedBursts || 0) >= clampInt(options.pingFailBursts, 1, 20, 2);

  // Реле двери недоступно — работаем без учёта двери (checkHealth сообщит об этом)
  var doorMode = !!(options.requireDoor && trimStr(options.doorInService) && inp.doorIn !== null);
  var ex = variables.lastExitAt || 0;
  if (ex <= arr) ex = 0;

  // 5. Режим «дома без сети»: после прихода телефон ни разу не был в сети
  //    (Wi-Fi выключен или хаб только что перезапущен). Тишина сети ничего не значит,
  //    уход — только по свежему выходу из геозоны (после выхода в дверь, если она есть).
  var real = variables.lastSeenReal || 0;
  if (real < arr) {
    // После перезапуска хаба: человека, возможно, уже нет, а геозона давно ВЫКЛ (без свежего фронта)
    if (variables.startCheck && pingOk) {
      var sv = now - arr;
      if (inp.geo === false && sv >= minToMs(options.startVerifyMin, 5)) {
        setAway(variables, options, now, "проверка после перезапуска: сети нет, геозона ВЫКЛ, ping не отвечает", false);
        return;
      }
      var slowMs = minToMs(options.leaveSlowMin, 90);
      if (!trimStr(options.geoService) && slowMs > 0 && !isNightTime(options) && sv >= slowMs) {
        setAway(variables, options, now, "проверка после перезапуска: сети нет " + Math.round(sv / 60000) + " мин", false);
        return;
      }
    }
    if (geo !== false) return;
    if (doorMode && !(ex && gOffFresh >= ex - slack)) return;
    if (now - gOffFresh < minToMs(options.leaveFastMin, 3)) return;
    if (!pingOk) return;
    setAway(variables, options, now, "дома без сети: " + (doorMode ? "выход в дверь, затем " : "") + "выход из геозоны", false);
    return;
  }

  // 6. Обычный режим — выбор пути ухода
  var seen = variables.lastSeenLAN || now;
  // Выход в дверь, который мог быть «его»: телефон не видели сильно позже него
  if (ex && !(ex >= (variables.lastSeenStrong || 0) - slack && ex >= real - Math.max(slack, lagMs))) ex = 0;
  var gOff = (gOffFresh && gOffFresh >= seen - slack) ? gOffFresh : 0;

  var limitMin = null, why = "", slow = false;
  if (doorMode) {
    if (!ex) return;                                           // не было выхода — не уходим
    if (real >= ex - corr) {                                   // телефон пропал вместе с выходом
      if (geo === false) { limitMin = intOr(options.leaveFastMin, 3);  why = "выход в дверь, геозона ВЫКЛ"; }
      else               { limitMin = intOr(options.leaveDoorMin, 10); why = "выход в дверь, геозона " + (geo === true ? "ВКЛ (залипла?)" : "н/д"); }
    } else if (geo === false && gOff > ex) {                   // спал, но после двери вышел из геозоны
      limitMin = intOr(options.leaveFastMin, 3); why = "выход в дверь, затем выход из геозоны";
    } else {
      slow = true;
    }
  } else {
    if (geo === false && gOff) { limitMin = intOr(options.leaveFastMin, 3); why = "выход из геозоны"; }
    else slow = true;
  }

  if (slow) {
    var night = isNightTime(options);
    limitMin = night ? intOr(options.nightSlowMin, 0) : intOr(options.leaveSlowMin, 90);
    if (limitMin <= 0) return;                                 // 0 — медленным путём не уходим
    why = "давно нет в сети" + (night ? " (ночь)" : "") + (doorMode ? ", была дверь" : "");
  }

  var silentMs = now - seen;
  if (silentMs < limitMin * 60000) return;
  if (!pingOk) return;

  setAway(variables, options, now, why + ", сеть молчит " + Math.round(silentMs / 60000) + " мин", geo === true);
}

// ═══════════════════════════════════════════════════════════════════════════
// ЧЕЛОВЕКА НЕТ — ищем основания для прихода
// ═══════════════════════════════════════════════════════════════════════════
function evalAway(inp, now, variables, options) {
  var a = variables.armed;
  if (inp.hb === true && a.hb)         { setHome(variables, options, now, "Homebridge", true); return; }
  if (inp.router === true && a.router) { setHome(variables, options, now, "роутер", true); return; }

  if (options.geoArrive && variables.geoOnAt && variables.geoOnAt > (variables.awayAt || 0)) {
    setHome(variables, options, now, "геозона", false);
    variables.geoArrivedAt = now;
    return;
  }

  // Ожидание после неподтверждённой геозоны: вход в дверь при геозоне ВКЛ = пришёл
  if (variables.geoWaitUntil) {
    if (inp.geo === false || now > variables.geoWaitUntil) {
      variables.geoWaitUntil = undefined;
      log(options, variables, "ожидание входа после геозоны завершено");
    } else if (inp.geo === true && variables.lastEntryAt && variables.lastEntryAt > (variables.awayAt || 0)) {
      setHome(variables, options, now, "вход в дверь при геозоне ВКЛ (после неподтверждённого прихода)", false);
      return;
    }
  }

  // Открыли дверь снаружи — сразу проверяем телефон, не дожидаясь датчиков
  var ip = trimStr(options.ipAddress);
  if (ip && variables.lastEntryAt && variables.lastEntryAt > (variables.awayAt || 0) &&
      now - variables.lastEntryAt < 5 * 60000 &&
      now - (variables.lastPingAt || 0) >= 20000) {
    variables.lastPingAt = now;
    if (doPing(ip, options, variables, "после входа в дверь")) setHome(variables, options, now, "ping после входа в дверь", true);
  }
}

// ═══════════════════════════════════════════════════════════════════════════
// СОСТОЯНИЯ
// ═══════════════════════════════════════════════════════════════════════════
function seenLAN(variables, now, strong) {
  variables.lastSeenLAN = now;
  variables.lastSeenReal = now;
  variables.startCheck = undefined;
  if (strong) variables.lastSeenStrong = now;
  variables.failedBursts = 0;
  variables.geoArrivedAt = undefined;
}

function markHome(variables, now, byLan) {
  variables.state = 1;
  variables.startCheck = undefined;
  variables.geoWaitUntil = undefined;
  variables.arrivedAt = now;
  variables.lastSeenLAN = now;
  if (byLan) { variables.lastSeenStrong = now; variables.lastSeenReal = now; }
  variables.failedBursts = 0;
  variables.geoArrivedAt = undefined;
}

function markAway(variables, now) {
  variables.state = 0;
  variables.startCheck = undefined;
  variables.geoWaitUntil = undefined;
  variables.awayAt = now;
  variables.geoArrivedAt = undefined;
  variables.armed = { hb: false, router: false };
}

function setHome(variables, options, now, reason, byLan) {
  markHome(variables, now, byLan);
  writeOut(variables, 1);
  log(options, variables, "ПРИШЁЛ — " + reason);
  if (byLan && trimStr(options.geoService)) {
    var g = readBool(options.geoService, HC.On);
    if (g === false) {
      log(options, variables, "приход по сети, геозона не сработала");
      if (options.syncGeoOnLan) setGeo(variables, options, true);
    }
  }
}

// allowGeoReset — уход решён по сети/двери при геозоне ВКЛ; при уходе по самой геозоне не трогаем её
function setAway(variables, options, now, reason, allowGeoReset) {
  markAway(variables, now);
  writeOut(variables, 0);
  log(options, variables, "УШЁЛ — " + reason);
  if (allowGeoReset && options.resetGeoOnAway) setGeo(variables, options, false);
}

function writeOut(variables, v) {
  var svc = variables.outSvc;
  if (!svc) return;
  var c = svc.getCharacteristic(HC.OccupancyDetected);
  if (c && c.getValue() !== v) c.setValue(v);
}

// Записать геозону. Запоминаем значение как текущее, чтобы не получить ложный фронт.
function setGeo(variables, options, on) {
  var uuid = trimStr(options.geoService);
  if (!uuid) return;
  try {
    var svc = getService(uuid);
    var c = svc ? svc.getCharacteristic(HC.On) : null;
    if (c && c.getValue() !== on) {
      if (variables.prev) variables.prev.geo = on;
      c.setValue(on);
      log(options, variables, "геозона " + (on ? "включена (приход по сети)" : "сброшена в ВЫКЛ"));
    }
  } catch (e) {
    console.warn(TAG + "запись геозоны: " + e.message);
  }
}

// Последний признак ухода (выход в дверь / выход из геозоны), относящийся к текущему молчанию
function leaveHintAt(variables, slack) {
  var h = Math.max(variables.geoOffAt || 0, variables.lastExitAt || 0);
  if (!h || h <= (variables.arrivedAt || 0)) return 0;
  if (h < (variables.lastSeenStrong || 0) - slack) return 0;
  return h;
}

// ═══════════════════════════════════════════════════════════════════════════
// КОНТРОЛЬ ИСТОЧНИКОВ И TELEGRAM
// ═══════════════════════════════════════════════════════════════════════════
function checkHealth(inp, now, variables, options) {
  var items = [];
  if (trimStr(options.geoService))
    items.push({ k: "geo", ok: inp.geo !== null, shared: false,
      bad: "геозона недоступна — уход только по сети и двери",
      good: "геозона снова доступна" });
  if (trimStr(options.hbService))
    items.push({ k: "hb", ok: inp.hb !== null, shared: false,
      bad: "датчик HB недоступен",
      good: "датчик HB снова доступен" });
  if (trimStr(options.routerHealthService))
    items.push({ k: "router", ok: inp.routerPlugin === true, shared: true,
      bad: "плагин роутера не работает (сам роутер не в сети) — данные роутера не учитываются",
      good: "плагин роутера снова работает" });
  if (trimStr(options.doorInService))
    items.push({ k: "doorIn", ok: inp.doorIn !== null, shared: true,
      bad: "реле двери (выход изнутри) недоступно" + (options.requireDoor ? " — уход определяется БЕЗ учёта двери" : ""),
      good: "реле двери (выход изнутри) снова доступно" + (options.requireDoor ? " — уход снова по двери" : "") });
  if (trimStr(options.doorOutService))
    items.push({ k: "doorOut", ok: inp.doorOut !== null, shared: true,
      bad: "реле двери (вход снаружи) недоступно — вход в дверь не отслеживается",
      good: "реле двери (вход снаружи) снова доступно" });

  var h = variables.health || {};
  var delay = minToMs(options.alertDelayMin, 5);
  for (var i = 0; i < items.length; i++) {
    var it = items[i];
    var st = h[it.k];
    if (!st) { st = { ok: it.ok, since: now, reported: true }; h[it.k] = st; }  // исходно считаем «в порядке»
    if (st.ok !== it.ok) { st.ok = it.ok; st.since = now; }
    if (st.ok !== st.reported && now - st.since >= delay) {
      st.reported = st.ok;
      var msg = (st.ok ? "✅ " + it.good : "⚠️ " + it.bad);
      if (st.ok) log(options, variables, msg); else console.warn(TAG + (variables.label || "") + ": " + msg);
      if (!it.shared || options.tgShared) sendTg(options, variables, msg);
    }
  }
  variables.health = h;

  // «Дома» без подтверждения: режим «не дома» и камеры могут не включиться
  var hrs = intOr(options.homeUnconfirmedHours, 6);
  if (variables.state !== 1 || hrs <= 0) { variables.unconfAlerted = undefined; return; }
  var ev = Math.max(variables.lastSeenReal || 0, variables.arrivedAt || 0);
  if (inp.geo === true || inp.hb === true || inp.router === true) { variables.unconfAlerted = undefined; return; }
  if (!variables.unconfAlerted && now - ev >= hrs * 3600000) {
    variables.unconfAlerted = true;
    var why = "телефона нет в сети" + (trimStr(options.geoService) ? ", геозона " + (inp.geo === false ? "ВЫКЛ" : "н/д") : "");
    var m = "⚠️ числится ДОМА уже " + Math.round((now - ev) / 3600000) + " ч без подтверждения (" + why + "). Режим «не дома» и камеры могут не включиться.";
    console.warn(TAG + (variables.label || "") + ": " + m);
    sendTg(options, variables, m);
  }
}

function sendTg(options, variables, text) {
  if (!options || !options.tgEnabled) return;
  var msg = "🏠 " + (variables.label || "Присутствие") + "\n" + text;
  try {
    if (typeof global !== "undefined" && global && typeof global.sendTG === "function") {
      global.sendTG(msg);                          // общая функция отправки из глобальных сценариев
      return;
    }
    var ch = trimStr(options.tgChannel) || "telegram_1";
    Notify.text(String(msg).replace(/_/g, "\\_")).to(ch).send();
  } catch (e) {
    console.error(TAG + "Telegram: " + e.message);
  }
}

// ═══════════════════════════════════════════════════════════════════════════
// ВВОД / ВЫВОД
// ═══════════════════════════════════════════════════════════════════════════
// Серия ping с подробным логом (если включён)
function doPing(ip, options, variables, why) {
  var t0 = Date.now();
  var ok = pingBurst(ip, options);
  if (options.pingLogVerbose) {
    log(options, variables, "ping " + ip + " (" + why + "): " + (ok ? "ОТВЕТИЛ" : "нет ответа") + " за " + (Date.now() - t0) + " мс");
  }
  return ok;
}

function pingBurst(ip, options) {
  var n = clampInt(options.pingTries, 1, 5, 2);
  for (var i = 0; i < n; i++) {
    try { if (UtilsNet.ping(ip) === true) return true; }
    catch (e) { console.warn(TAG + "ping " + ip + ": " + e.message); return false; }
  }
  return false;
}

function readOcc(uuid, offlineIsFalse) {
  var v = readChar(uuid, HC.OccupancyDetected, offlineIsFalse);
  if (v === null) return null;
  return (v === 1 || v === true || v === "1");
}

function readBool(uuid, charType) {
  var v = readChar(uuid, charType);
  if (v === null) return null;
  return (v === true || v === 1 || v === "1" || v === "true");
}

// null — источник не выбран, недоступен (offline) или ошибка.
// offlineIsFalse — вернуть 0 вместо null, если устройство offline
function readChar(uuid, charType, offlineIsFalse) {
  if (!uuid || uuid === "") return null;
  try {
    var svc = getService(uuid);
    if (!svc) return null;
    var acc = svc.getAccessory();
    var online = null;
    acc.getServices().forEach(function (s) {
      if (s.getType() === HS.AccessoryInformation) {
        var o = s.getCharacteristic(HC.C_Online);
        if (o) online = o.getValue();
      }
    });
    if (online === false) return offlineIsFalse ? 0 : null;
    var c = svc.getCharacteristic(charType);
    if (!c) return null;
    var v = c.getValue();
    return (v === undefined) ? null : v;
  } catch (e) {
    console.warn(TAG + "чтение " + uuid + ": " + e.message);
    return null;
  }
}

function getService(uuid) {
  if (!uuid || uuid === "") return null;
  try {
    var parts = uuid.split(".");
    var acc = Hub.getAccessory(parts[0]);
    return acc ? acc.getService(parts[1]) : null;
  } catch (e) {
    return null;
  }
}

function getServiceList(serviceTypes, charType) {
  var result = [{ name: { ru: "Не выбрано", en: "Not selected" }, value: "" }];
  var unsorted = [];
  Hub.getAccessories().forEach(function (acc) {
    acc.getServices().filter(function (svc) {
      return serviceTypes.indexOf(svc.getType()) >= 0;
    }).forEach(function (svc) {
      if (svc.getCharacteristic(charType)) {
        var accName = acc.getName();
        var svcName = svc.getName();
        var roomName = acc.getRoom() ? acc.getRoom().getName() : "";
        var label = roomName + " → " + (accName === svcName ? accName : accName + " " + svcName) + " (" + svc.getUUID() + ")";
        unsorted.push({ name: { ru: label, en: label }, value: svc.getUUID() });
      }
    });
  });
  unsorted.sort(function (a, b) { return a.name.ru.localeCompare(b.name.ru); });
  unsorted.forEach(function (s) { result.push(s); });
  return result;
}

// ═══════════════════════════════════════════════════════════════════════════
// УТИЛИТЫ
// ═══════════════════════════════════════════════════════════════════════════
function isNightTime(options) {
  var now = new Date();
  var cur = now.getHours() * 60 + now.getMinutes();
  var s = parseTime(options.nightStart, 23 * 60);
  var e = parseTime(options.nightEnd, 8 * 60);
  if (s === e) return false;
  return (s > e) ? (cur >= s || cur < e) : (cur >= s && cur < e);
}

function parseTime(str, def) {
  var m = String(str || "").match(/^\s*(\d{1,2}):(\d{2})\s*$/);
  if (!m) return def;
  return parseInt(m[1], 10) * 60 + parseInt(m[2], 10);
}

function intOr(v, def) {
  var n = parseInt(v, 10);
  return isNaN(n) || n < 0 ? def : n;
}

function clampInt(v, lo, hi, def) {
  var n = parseInt(v, 10);
  if (isNaN(n)) n = def;
  return n < lo ? lo : (n > hi ? hi : n);
}

function minToMs(v, def) { return intOr(v, def) * 60000; }

function trimStr(s) { return s ? String(s).replace(/^\s+|\s+$/g, "") : ""; }

function makeLabel(svc) {
  var s = "?";
  try { s = svc.getAccessory().getName() + " / " + svc.getName(); } catch (e) {
    try { s = svc.getName(); } catch (e2) {}
  }
  return s;
}

function log(options, variables, msg) {
  if (options && options.logEnabled) console.info(TAG + (variables.label || "") + ": " + msg);
}
